require_once __DIR__.'/includes/functions.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();require_once __DIR__.'/config/database.php';if(is_logged_in())redirect('profile.php');
$errors=[];$name='';$email='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$password=(string)($_POST['password']??'');$confirm=(string)($_POST['password_confirmation']??'');if(mb_strlen($name)<2||mb_strlen($name)>120)$errors[]='Аты-жөніңіз 2–120 таңба аралығында болуы керек.';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>190)$errors[]='Жарамды email мекенжайын енгізіңіз.';if(mb_strlen($password)<8)$errors[]='Құпиясөз кемінде 8 таңба болуы керек.';if(strlen($password)>72)$errors[]='Құпиясөз 72 байттан аспауы керек.';if($password!==$confirm)$errors[]='Құпиясөздер сәйкес келмейді.';if(!$errors){$check=$pdo->prepare('SELECT id FROM users WHERE email=:email');$check->execute(['email'=>$email]);if($check->fetch())$errors[]='Бұл email бұрын тіркелген. Кіру бетіне өтіңіз.';else{try{$insert=$pdo->prepare('INSERT INTO users (name,email,password) VALUES (:name,:email,:password)');$insert->execute(['name'=>$name,'email'=>$email,'password'=>password_hash($password,PASSWORD_DEFAULT)]);$_SESSION['flash']='Тіркелу сәтті аяқталды. Енді аккаунтыңызға кіріңіз.';redirect('login.php');}catch(PDOException $e){if($e->getCode()==='23000')$errors[]='Бұл email бұрын тіркелген.';else throw $e;}}}}
$pageTitle='Тіркелу — Apple Store';require __DIR__.'/includes/header.php';
?><section class="auth-layout"><div class="auth-card"><p class="eyebrow">ЖАҢА АККАУНТ</p><h1>Қосылыңыз.</h1><p class="auth-subtitle">Бір минутта жеке кабинетіңізді жасаңыз.</p><?php if($errors): ?><div class="alert alert-error" role="alert"><?php foreach($errors as $error): ?><p><?= e($error) ?></p><?php endforeach; ?></div><?php endif; ?><form method="post" class="form-stack" novalidate><?= csrf_field() ?><label>Аты-жөні<input type="text" name="name" value="<?= e($name) ?>" autocomplete="name" maxlength="120" required></label><label>Email<input type="email" name="email" value="<?= e($email) ?>" autocomplete="email" maxlength="190" required></label><label>Құпиясөз<input type="password" name="password" autocomplete="new-password" minlength="8" required><small>Кемінде 8 таңба.</small></label><label>Құпиясөзді қайталаңыз<input type="password" name="password_confirmation" autocomplete="new-password" minlength="8" required></label><button class="button button-dark button-full" type="submit">Тіркелу</button></form><p class="auth-foot">Аккаунтыңыз бар ма? <a href="login.php">Кіру</a></p></div><aside class="auth-aside"><span></span><p>Өз талғамыңызға сай<br>технологияны табыңыз.</p></aside></section><?php require __DIR__.'/includes/footer.php'; ?>
